CREATE TABLE ORDERS (ID INTEGER NOT NULL, QTY INTEGER, PRICE NUMERIC(9,2), TOOLID INTEGER, NOTE VARCHAR(80), WHENAT TIMESTAMP, FLAG BOOLEAN, DESCR BLOB SUB_TYPE TEXT, OLDCOL INTEGER, USEDCOL INTEGER, CONSTRAINT PK_O PRIMARY KEY (ID));
CREATE TABLE TOOLS (ID INTEGER NOT NULL, NAME VARCHAR(30), CONSTRAINT PK_T PRIMARY KEY (ID));
